# Knowledge Bundle Builder demo: seed expansion with reading order + completeness check.
GRAPH={"intro":["basics"],"basics":["advanced","glossary"],"advanced":[],"glossary":[]}
DEPTH={"intro":0,"basics":1,"advanced":2,"glossary":2}
def collect(seed,max_depth=2):
    seen={}; stack=[(seed,0)]
    while stack:
        n,d=stack.pop()
        if n in seen or d>max_depth: continue
        seen[n]=d; stack.extend((m,d+1) for m in GRAPH.get(n,[]))
    return sorted(seen,key=lambda n:(seen[n],n))
bundle=collect("intro")
print("bundle reading order:",bundle)
dangling=[m for n in bundle for m in GRAPH.get(n,[]) if m not in bundle]
print("dangling references:",dangling or "none - bundle complete")

